//! Embeds the icon (`assets/holt.ico`) and the version data in the Windows executable.
//! The `.ico` is generated by `scripts/generate-icon.ps1` from the logo drawing (`icons.rs`).
//! On Linux, a release build also puts Holt in the user's app menu (see [`install_desktop_entry`]).

use std::path::{Path, PathBuf};

fn main() {
    println!("cargo:rerun-if-changed=assets/holt.ico");
    println!("cargo:rerun-if-changed=build.rs");
    let target_os = std::env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    if target_os == "windows" {
        let mut res = winresource::WindowsResource::new();
        res.set_icon("assets/holt.ico");
        res.set("ProductName", "Holt");
        res.set("FileDescription", "Holt");
        if let Err(e) = res.compile() {
            // Without the resource compiler (rc.exe) the app still builds, just without the icon in the .exe.
            println!("cargo:warning=could not embed the icon in the executable: {e}");
        }
    }
    if target_os == "linux" {
        install_desktop_entry();
    }
}

/// Writes `~/.local/share/applications/holt.desktop` (pointing at the binary this build makes) and the icon, so
/// the app shows up in the menu right after `cargo build --release`; Wayland desktops take the icon from there
/// (the window's app id is `holt`). Only for release builds on the machine that runs them: not in CI, not when
/// cross-compiling, not with `HOLT_NO_DESKTOP_ENTRY`. `scripts/install-desktop.sh` does the same by hand.
fn install_desktop_entry() {
    println!("cargo:rerun-if-changed=assets/holt.desktop");
    println!("cargo:rerun-if-changed=assets/holt.png");
    println!("cargo:rerun-if-env-changed=HOLT_NO_DESKTOP_ENTRY");
    println!("cargo:rerun-if-env-changed=CI");
    let var = |k: &str| std::env::var_os(k).filter(|v| !v.is_empty());
    if std::env::var("PROFILE").as_deref() != Ok("release")
        || var("CI").is_some()
        || var("HOLT_NO_DESKTOP_ENTRY").is_some()
        || std::env::var("HOST") != std::env::var("TARGET")
    {
        return;
    }
    let Some(data) = var("XDG_DATA_HOME").map(PathBuf::from).or_else(|| var("HOME").map(|h| PathBuf::from(h).join(".local/share"))) else {
        return;
    };
    // OUT_DIR is `<target>/[<triple>/]release/build/holt-<hash>/out`: the binary lands in `.../release/`.
    let Some(bin) = var("OUT_DIR").and_then(|o| Path::new(&o).ancestors().nth(3).map(|d| d.join("holt"))) else { return };
    let desktop = data.join("applications/holt.desktop");
    let icon = data.join("icons/hicolor/256x256/apps/holt.png");
    // Deleted by hand (or uninstalled): the next build writes them again.
    println!("cargo:rerun-if-changed={}", desktop.display());
    println!("cargo:rerun-if-changed={}", icon.display());
    let result = (|| -> std::io::Result<()> {
        let template = std::fs::read_to_string("assets/holt.desktop")?;
        std::fs::create_dir_all(desktop.parent().expect("parent"))?;
        std::fs::create_dir_all(icon.parent().expect("parent"))?;
        std::fs::copy("assets/holt.png", &icon)?;
        std::fs::write(&desktop, template.replace("@EXEC@", &bin.display().to_string()))?;
        // Written now, they would look newer than this run and every build would run this again (and recompile the
        // app): they take the template's time instead.
        let stamp = std::fs::metadata("assets/holt.desktop")?.modified()?;
        for f in [&desktop, &icon] {
            std::fs::File::options().write(true).open(f)?.set_modified(stamp)?;
        }
        Ok(())
    })();
    if let Err(e) = result {
        println!("cargo:warning=could not add Holt to the app menu ({}): {e}", desktop.display());
    }
}
